def get_max_triples(n):
    # Calculate array a
    a = [i * i - i + 1 for i in range(1, n+1)]

    # Count how many triples are there where sum of elements is divisible by 3
    count = 0
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                if (a[i] + a[j] + a[k]) % 3 == 0:
                    count += 1

    return count
```
